640	// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
641	// If stopAt is provided, stops when reaching that commit (exclusive).
642	// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
643	// It distinguishes between merge commits (bringing in other branches) and regular commits
644	// (actual branch work) to avoid false warnings after merging main.
645	func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointsResult {
646		result := &branchCheckpointsResult{}
647		branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
648		const maxCommits = 100 // Limit search depth
649		totalChecked := 0
650	
651		current := start
652		for current != nil && totalChecked < maxCommits {
653			// Stop if we've reached the boundary
654			if stopAt != nil && current.Hash == *stopAt {
655				break
656			}
657	
658			// Check for checkpoint trailer
659			if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
660				result.checkpointIDs = cpIDs
661				result.commitHash = current.Hash.String()
662				result.commitMessage = current.Message
663				// Only warn about branch work commits, not merge commits
664				result.newerCommitsExist = branchWorkCommits > 0
665				result.newerCommitCount = branchWorkCommits
666				return result
667			}
668	
669			// Only count regular commits (not merge commits) as "branch work"
670			if current.NumParents() <= 1 {
671				branchWorkCommits++
672			}
673	
674			totalChecked++
675	
676			// Move to parent (first parent for merge commits - follows the main line)
677			if current.NumParents() == 0 {
678				break
679			}
680			parent, err := current.Parent(0)
681			if err != nil {
682				// Can't get parent, treat as end of history
683				break
684			}
685			current = parent
686		}
687	
688		// No checkpoint found
689		return result
690	}
