	summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
	if summaryErr != nil {
		return nil, summaryErr
	}
	if !hasSingleV1FallbackSession(summary, sessionIndex) {
		return nil, err
	}
