func promoteRemoteTrackingMetadataBranch(ctx context.Context, repo *git.Repository) {
    localRefName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName), true)
    if err != nil {
        return
    }
    if local, err := repo.Reference(localRefName, true); err == nil {
        if local.Hash() == remoteRef.Hash() {
            return
        }
        if !strategy.IsAncestorOf(ctx, repo, local.Hash(), remoteRef.Hash()) {
            // diverged or ahead — leave local alone
            logging.Debug(ctx, ...)
            return
        }
    }
    strategy.SafelyAdvanceLocalRef(ctx, repo, localRefName, remoteRef.Hash())
}

